mapper.select:
select id, datasource_id as datasourceId, table_id as tableId, rule_description as ruleDescription, rule_name as ruleName, rule_condition as ruleCondition, create_user as createUser, update_user as updateUser, create_time as createTime, update_time as updateTime from table_filter_rule
table_id = #{tableId}
rule_name = #{ruleName}
order by update_time desc
